mapper.select:
select BS.BOOKSET_ID as booksetId, BS.SUBJECT_NO as subjectNo, BS.SUBJECT_NAME as subjectName, BS.FSUBJECT_ID as fsubjectId, BS.BAL_FLAG as balFlag, BS.SUBJECT_TYPE as subjectType, BS.SUBJECT_LEVEL as subjectLevel, BS.ACC_QUA_FLAG as accQuaFlag, BS.ACC_INT_FLAG as accIntFlag, BS.OVERDRAWN_FLAG as overdrawnFlag, BS.GEN_DETSUB_FLAG as genDetsubFlag,/**是否生成四级科目**/ BS.GEN_DETSUB_FLAG as genDetsubFlagCode, BAS.SUBJECT_INTERNAL_NAME as baseSubjectNature, BS.CREATE_USER as createUser, BS.CREATE_DEPT as createDept, BS.CREATE_TIME as createTime, BS.UPDATE_USER as updateUser, BS.UPDATE_TIME as updateTime from BOK_SUBJECT BS LEFT JOIN BOK_BOOKSET BB ON BS.BOOKSET_ID=BB.BOOKSET_ID LEFT JOIN BOK_SUBJECT_INTERNAL BAS ON BS.BASE_SUBJECT_NATURE = BAS.SUBJECT_INTERNAL_CODE
/** modify by yanya on 20191204 科目号随科目级别展示，原来级别向上取，现改为只取当前级别**/ BS.SUBJECT_LEVEL = #{subjectLevel}
AND BS.FSUBJECT_ID = #{fsubjectId}
AND BS.BOOKSET_ID = #{booksetId}
AND BS.SUBJECT_NO like #{subjectNo} || '%'
AND BS.SUBJECT_NAME like '%' || #{subjectName} || '%'
AND BS.SUBJECT_TYPE = #{subjectType}
AND BS.BAL_FLAG = #{balFlag}
order by BS.BOOKSET_ID,BS.SUBJECT_NO,BS.SUBJECT_LEVEL

SELECT
DISTINCT SUBJECT_NO id,
SUBJECT_NAME text
FROM BOK_SUBJECT


        BOOKSET_ID = #{booksetId}


        /** modify by yanya on 20191204 科目号随科目级别展示，原来级别向下取，现改为只取当前级别**/
      and  to_number(subject_level) = #{subjectLevel}


        AND (SUBJECT_NO like '%' || #{search} || '%'
        OR SUBJECT_NAME like '%' || #{search} || '%')


order by SUBJECT_NO

select SUBJECT_NO as id, SUBJECT_NAME as text FROM BOK_SUBJECT WHERE 1 = 1
AND BOOKSET_ID = #{booksetId}
AND SUBJECT_LEVEL = #{subjectLevel}
AND (SUBJECT_NO like '%' || #{search} || '%' OR SUBJECT_NAME like '%' || #{search} || '%')
GROUP BY SUBJECT_NO, SUBJECT_NAME

mapper.delete:
delete from BOK_SUBJECT
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and SUBJECT_NO like #{subjectNo,jdbcType=VARCHAR} || '%'

delete from BOK_SUBJECT_HAND_VALUE
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and SUBJECT_NO = #{subjectNo,jdbcType=VARCHAR}

mapper.select:
SELECT hand.BOOKSET_ID booksetId, hand.SUBJECT_INTERNAL_CODE subjectInternalCode, hand.HAND_CODE handCode, dict.DICT_CNNAME handName FROM BOK_SUBJECT_INTERNAL_HAND hand LEFT JOIN SYS_DATADICT dict ON dict.DICT_CODE = hand.HAND_CODE WHERE 1=1
and hand.HAND_CODE != #{default}
AND hand.SUBJECT_INTERNAL_CODE = #{subjectInternalCode}
order by hand.HAND_CODE desc

SELECT dict.ITEM_CODE id, dict.ITEM_VALUE text, dict.DICT_CODE dictCode, datadict.DICT_CNNAME dictName FROM BOK_SUBJECT_INTERNAL_HAND hand LEFT JOIN SYS_DATADICT datadict ON datadict.DICT_CODE = hand.HAND_CODE LEFT JOIN SYS_DATADICT_LIST dict ON dict.DICT_CODE = hand.HAND_CODE WHERE 1=1
AND hand.SUBJECT_INTERNAL_CODE = #{subjectInternalCode}
AND hand.HAND_CODE = #{handCode}
order by hand.HAND_CODE DESC
